<?php
declare(strict_types=1);
namespace App\Interface\Http\Taxonomy\Controller;
use App\Application\Identity\DTO\Request\AccessTokenRequestDto;use App\Application\Identity\Service\AuthService;use App\Application\Taxonomy\DTO\Request\CreateTaxonomySubjectRequestDto;use App\Application\Taxonomy\DTO\Request\ListTaxonomySubjectsRequestDto;use App\Application\Taxonomy\DTO\Request\UpdateTaxonomySubjectRequestDto;use App\Application\Taxonomy\Service\CreateTaxonomySubjectService;use App\Application\Taxonomy\Service\ListTaxonomySubjectsService;use App\Application\Taxonomy\Service\UpdateTaxonomySubjectService;use App\Domain\Identity\Exception\UnavailableUserException;use App\Infrastructure\Http\ApiResponseFactory;use DomainException;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;
final class TaxonomyController { public function __construct(private readonly AuthService $auth,private readonly CreateTaxonomySubjectService $create,private readonly ListTaxonomySubjectsService $list,private readonly UpdateTaxonomySubjectService $update,private readonly ApiResponseFactory $responses){} public function list(ServerRequestInterface $request,ResponseInterface $response,AccessTokenRequestDto $access,ListTaxonomySubjectsRequestDto $input):ResponseInterface{if(!$this->admin($request,$response,$access))return $this->forbidden($request,$response);$page=$this->list->list($input);return $this->responses->paginated($response,$page->items,(string)$request->getAttribute('request_id'),$page->page,$page->perPage,$page->total);} public function create(ServerRequestInterface $request,ResponseInterface $response,AccessTokenRequestDto $access,CreateTaxonomySubjectRequestDto $input):ResponseInterface{return $this->save($request,$response,$access,fn()=>$this->create->create($input),201);} public function update(ServerRequestInterface $request,ResponseInterface $response,AccessTokenRequestDto $access,UpdateTaxonomySubjectRequestDto $input):ResponseInterface{return $this->save($request,$response,$access,fn()=>$this->update->update($input),200);} private function save(ServerRequestInterface $request,ResponseInterface $response,AccessTokenRequestDto $access,callable $operation,int $status):ResponseInterface{if(!$this->admin($request,$response,$access))return $this->forbidden($request,$response);try{$result=$operation();}catch(DomainException|\InvalidArgumentException $e){return $this->responses->problem($response,'VALIDATION_FAILED','Um ou mais campos sao invalidos.',422,(string)$request->getAttribute('request_id'),[['field'=>'request','code'=>'INVALID_VALUE','message'=>$e->getMessage()]]);}return $this->responses->success($response,$result,(string)$request->getAttribute('request_id'),$status);} private function admin(ServerRequestInterface $request,ResponseInterface $response,AccessTokenRequestDto $access):bool{try{$user=$this->auth->currentUser($access);return in_array('ADMIN',$user->roles,true);}catch(DomainException|UnavailableUserException){return false;}} private function forbidden(ServerRequestInterface $request,ResponseInterface $response):ResponseInterface{return $this->responses->problem($response,'FORBIDDEN','Permissao insuficiente.',403,(string)$request->getAttribute('request_id'));} }
